// AI Service — talks to the InterviewX server (Groq llama-3.1-8b-instant).
//
// HONESTY CONTRACT: every result carries a `source` field:
//   'llm'      -> generated by the LLM via the server
//   'fallback' -> local heuristic / built-in question bank, NOT AI
// The UI must always surface which one the user is looking at.

class AIService {
    constructor() {
        this.llmAvailable = false;
        this.model = null;
        this.checkHealth();
    }

    async checkHealth() {
        try {
            const res = await fetch(InterviewXConfig.api.base + InterviewXConfig.api.healthPath);
            const data = await res.json();
            this.llmAvailable = Boolean(data.llm);
            this.model = data.model;
        } catch {
            // Opened as a plain file or server down: no LLM.
            this.llmAvailable = false;
            this.model = null;
        }
        this.updateStatusBadge();
    }

    updateStatusBadge() {
        const badge = document.getElementById('aiStatusBadge');
        if (!badge) return;
        if (this.llmAvailable) {
            badge.textContent = `● AI live — Groq ${this.model}`;
            badge.className = 'ai-status llm';
            badge.title = 'Questions and feedback are generated by an LLM through the local server.';
        } else {
            badge.textContent = '● Offline mode — no AI';
            badge.className = 'ai-status offline';
            badge.title = 'No LLM available. Questions come from the built-in bank and scoring is a simple word-count heuristic, not AI. Run server.js with a GROQ_API_KEY to enable AI.';
        }
    }

    // ------------------------------------------------------------------
    // Question generation
    // ------------------------------------------------------------------
    async generateQuestions(role, difficulty, count = 6) {
        const res = await fetch(InterviewXConfig.api.base + InterviewXConfig.api.questionsPath, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ role, difficulty, count })
        });
        if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            throw new Error(body.message || `Question generation failed (${res.status})`);
        }
        return res.json(); // { source:'llm', model, questions:[...] }
    }

    // ------------------------------------------------------------------
    // Answer feedback
    // ------------------------------------------------------------------
    async analyzeAnswer(question, answer, role, metrics) {
        if (this.llmAvailable) {
            try {
                const res = await fetch(InterviewXConfig.api.base + InterviewXConfig.api.feedbackPath, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ question, answer, role, metrics })
                });
                if (res.ok) return await res.json();
                console.warn('Feedback endpoint failed, using local heuristic');
            } catch (err) {
                console.warn('Feedback request error, using local heuristic:', err);
            }
        }
        return this.heuristicAnalysis(answer, metrics);
    }

    // Plain word-count/filler heuristic. Labeled as NOT AI everywhere it is shown.
    heuristicAnalysis(answer, metrics = {}) {
        const wordCount = metrics.wordCount || 0;
        const fillerCount = metrics.fillerCount || 0;
        const strengths = [];
        const gaps = [];
        let score = 4;

        if (wordCount >= 40 && wordCount <= 180) {
            score += 2;
            strengths.push('Answer length is in a good range');
        } else if (wordCount < 20) {
            score -= 2;
            gaps.push('Answer is very short — expand with detail');
        } else if (wordCount > 220) {
            score -= 1;
            gaps.push('Answer runs long — tighten it up');
        }

        if (fillerCount === 0) {
            score += 1;
            strengths.push('No filler words detected');
        } else if (fillerCount >= 4) {
            score -= 1;
            gaps.push(`${fillerCount} filler words detected — slow down and pause instead`);
        }

        if ((metrics.responseTime || 0) < 4 && wordCount < 30) {
            gaps.push('Answered very fast — take a moment to structure your thoughts');
        }

        if (strengths.length === 0) strengths.push('You completed an answer');
        if (gaps.length === 0) gaps.push('Heuristic checks passed — content quality was not evaluated');

        return {
            source: 'fallback',
            model: null,
            score: clamp(score, 1, 10),
            justification: 'Offline heuristic score based only on answer length, filler words, and timing. The content of your answer was NOT evaluated — this is not AI feedback.',
            strengths,
            gaps,
            suggestion: 'Start the server with a GROQ_API_KEY to get real LLM feedback on what you actually said.'
        };
    }

    // ------------------------------------------------------------------
    // Rendering
    // ------------------------------------------------------------------
    formatFeedback(analysis) {
        const isLLM = analysis.source === 'llm';
        const score = analysis.score;
        const tone = score >= 7 ? 'good' : score >= 5 ? 'mid' : 'bad';

        const badge = isLLM
            ? `<span class="source-badge llm" title="Generated by ${escapeHtml(analysis.model || 'LLM')}">🤖 LLM feedback · ${escapeHtml(analysis.model || '')}</span>`
            : '<span class="source-badge offline" title="Local heuristic — the content of your answer was not evaluated">⚠️ Offline heuristic — not AI</span>';

        const strengths = analysis.strengths.map(s => `<li>${escapeHtml(s)}</li>`).join('');
        const gaps = analysis.gaps.map(g => `<li>${escapeHtml(g)}</li>`).join('');

        return `
            <div class="feedback-card ${tone}">
                <div class="feedback-top">
                    <div class="score-ring ${tone}"><span>${score}</span><small>/10</small></div>
                    <div class="feedback-meta">
                        ${badge}
                        <p class="justification">${escapeHtml(analysis.justification)}</p>
                    </div>
                </div>
                <div class="feedback-cols">
                    <div class="feedback-block strengths">
                        <h4>Strengths</h4>
                        <ul>${strengths}</ul>
                    </div>
                    <div class="feedback-block gaps">
                        <h4>Gaps</h4>
                        <ul>${gaps}</ul>
                    </div>
                </div>
                <div class="feedback-block suggestion">
                    <h4>Next time</h4>
                    <p>${escapeHtml(analysis.suggestion)}</p>
                </div>
            </div>
        `;
    }
}

// Create global AI service instance
const aiService = new AIService();
